class Solution {

    /**
     * @param Integer $left
     * @param Integer $right
     * @return String
     */
    function abbreviateProduct($left, $right) {
        // Count trailing zeros by counting total 5s and 2s:
        // number of trailing zeros = minimum of (count of 2, count of 5)
        $count2 = 0;
        $count5 = 0;

        // To handle huge products, we'll keep track of:
        //  - trailing zeros count (C)
        //  - last 10 digits of product without trailing zeros (mod 10^10)
        //  - first 10 digits of product (using logs)

        $mod = 10000000000; // 10^10

        $lastDigits = 1;     // will keep track of last digits without trailing zeros (mod 10^10)
        $logSum = 0.0;       // sum of log10 for determining first digits

        for ($x = $left; $x <= $right; $x++) {
            // factor count of 2 and 5 in x
            $cur = $x;
            while ($cur % 2 == 0) {
                $count2++;
                $cur /= 2;
            }
            $cur = $x;
            while ($cur % 5 == 0) {
                $count5++;
                $cur /= 5;
            }
            // multiply lastDigits by x after dividing out 2s and 5s to keep track of last digits without trailing zeros
            $lastDigits = ($lastDigits * $cur) % $mod;

            // accumulate log10
            $logSum += log10($x);
        }

        // trailing zeros count
        $C = min($count2, $count5);

        // We removed C trailing zeros, so adjust lastDigits by dividing out 2s and 5s accordingly.
        // Actually, we already extracted 2s and 5s counts separately
        // and removed them from lastDigits by not including them in lastDigits multiplication.
        // So lastDigits is product / (2^count2 * 5^count5)
        // After removing trailing zeros (min(count2,count5)), product / (10^C) = lastDigits * (2^(count2 - C)*5^(count5 - C))
        // But since (count2 - C) and (count5 - C) are non-negative, and product ends with C zeros, 
        // the final product without trailing zeros equals lastDigits * 2^{count2-C} * 5^{count5-C}
        // However, lastDigits alone represents product without any 2s or 5s in x. To restore those left over 2s or 5s, we can multiply them back.
        // This multiplication can be big, so we just keep lastDigits as product without any 2s or 5s, then multiply the leftovers:
        $left2 = $count2 - $C;
        $left5 = $count5 - $C;

        // multiply leftover 2's
        for ($i=0; $i<$left2; $i++) {
            $lastDigits = ($lastDigits * 2) % $mod;
        }
        // multiply leftover 5's
        for ($i=0; $i<$left5; $i++) {
            $lastDigits = ($lastDigits * 5) % $mod;
        }

        // Number of digits in full product:
        $d = (int)floor($logSum) + 1 - $C;

        // Get first 10 digits:
        // product / 10^(d-10) = first 10 digits (integer part)
        $pow = $d - 10;
        $frac = $logSum - floor($logSum);
        $firstDigitsVal = pow(10, $frac + 9);
        // floor value may be float, so do string handling to get first 10 digits:
        // We get firstDigitsVal as a double, convert to string with no decimals:
        // sometimes due to floating point errors, floor might be off by 1
        $firstDigits = (int)floor($firstDigitsVal);

        // Process lastDigits to string, pad with zeros if needed to get up to 10 digits
        $lastStr = (string)$lastDigits;
        if (strlen($lastStr) < 10) {
            $lastStr = str_pad($lastStr, 10, "0", STR_PAD_LEFT);
        }

        // If full digits <= 10, just output product without trailing zeros + eC
        if ($d <= 10) {
            // In this case, product does not need abbreviation, just output product without trailing zeros and with eC
            // The product is product / 10^C
            // We can just compute product without trailing zeros by multiplying all numbers and removing trailing zeros:
            // But we already have lastDigits above (product without trailing zeros mod 10^10)
            // But if d<=10, product fits in regular integer or double, we can calculate exact number:
            // Let's calculate full product in int without trailing zeros (since d<=10 product fits in 64-bit integer)

            // Calculate product directly without trailing zeros:
            $prod = 1;
            for ($x = $left; $x <= $right; $x++) {
                $prod = bcmul((string)$prod, (string)$x);
            }
            // remove trailing zeros
            $prod = rtrim($prod, "0");

            return $prod . "e" . $C . " ";
        }

        // Otherwise, output abbreviated form: first 5 digits + "..." + last 5 digits + "eC "
        $first5 = (string)($firstDigits);
        if (strlen($first5) > 5) {
            $first5 = substr($first5, 0, 5);
        } else if (strlen($first5) < 5) {
            // pad with zeros
            $first5 = str_pad($first5, 5, "0", STR_PAD_RIGHT);
        }

        $last5 = substr($lastStr, -5);

        return $first5 . "..." . $last5 . "e" . $C . " ";
    }
}

